theorem mem_corePoints_of_separating [DecidableEq (FreeGroup α)]
    {S : Finset (FreeGroup α)} {g x : FreeGroup α}
    (hx : x ∈ allActionStates g.toWord) : x ∈ corePoints S g

theorem mem_corePoints_of_separating_suffix [DecidableEq (FreeGroup α)]
    {S : Finset (FreeGroup α)} {g : FreeGroup α} {u : List (α × Bool)}
    (hu : u ∈ List.tails g.toWord) {x : FreeGroup α}
    (hx : x ∈ actionStates u) : x ∈ corePoints S g

theorem coreCondition_tail {H : Subgroup (FreeGroup α)}
    {A : Set (LeftCosetQuotient H)} {x : α × Bool} {u : List (α × Bool)}
    (h : coreCondition A (x :: u)) : coreCondition A u

theorem nielsenEquivalent_closure_eq {A : Type*} [Group A] {n : ℕ}
    {x y : Fin n → A} (h : NielsenEquivalent x y) :
    Subgroup.closure (Set.range x) = Subgroup.closure (Set.range y)

theorem nielsenStep_closure_eq {A : Type*} [Group A] {n : ℕ}
    {x y : Fin n → A} (h : NielsenStep x y) :
    Subgroup.closure (Set.range x) = Subgroup.closure (Set.range y)

theorem nielsenEquivalent_mulLeft {A : Type*} [Group A] {n : ℕ}
    (x : Fin n → A) (i j : Fin n) (hij : i ≠ j) :
    NielsenEquivalent x (Function.update x i (x j * x i))

theorem nielsenEquivalent_mulRight_inv {A : Type*} [Group A] {n : ℕ}
    (x : Fin n → A) (i j : Fin n) (hij : i ≠ j) :
    NielsenEquivalent x (Function.update x i (x i * (x j)⁻¹))

theorem nielsenEquivalent_symm {A : Type*} [Group A] {n : ℕ}
    {x y : Fin n → A} (h : NielsenEquivalent x y) :
    NielsenEquivalent y x

theorem nielsenEquivalent_trans {A : Type*} [Group A] {n : ℕ}
    {x y z : Fin n → A} (hxy : NielsenEquivalent x y)
    (hyz : NielsenEquivalent y z) : NielsenEquivalent x z

theorem nielsenMinimal_nielsenReduced {n : ℕ}
    {x : Fin n → G ∗ H} (hmin : NielsenMinimal x) :
    NielsenReduced x

theorem word_length_rcons_le {b : Bool}
    (p : Monoid.CoprodI.Word.Pair (binaryFamily G H) b) :
    (Monoid.CoprodI.Word.rcons p).toList.length ≤ p.tail.toList.length + 1

theorem word_pair_tail_length_le {b : Bool}
    (w : Monoid.CoprodI.Word (binaryFamily G H)) :
    (Monoid.CoprodI.Word.equivPair b w).tail.toList.length ≤ w.toList.length

theorem exists_map_inl_of_idx_false {v : List (Sum G H)}
    (hv : ∀ a ∈ v, binarySumIndex (G := G) (H := H) a = false) :
    ∃ l : List G, v = l.map Sum.inl

theorem exists_map_inr_of_idx_true {v : List (Sum G H)}
    (hv : ∀ a ∈ v, binarySumIndex (G := G) (H := H) a = true) :
    ∃ l : List H, v = l.map Sum.inr

theorem separatedMap_binaryRunTag' {v : List (Sum G H)}
    {u : List (Sum G H)} (hv : v ∈ binaryRuns (G := G) (H := H) u) :
    separatedMap (binaryRunTag' (G := G) (H := H) v) = factorWordProd v

theorem isMonochromatic_reverse {a b : V} {p : Path a b} {color : Bool}
    (hp : L.IsMonochromatic p color) :
    L.IsMonochromatic p.reverse color

theorem loopNielsenEquivalent_read {b : V} {n : ℕ}
    {x y : Fin n → Path b b} (h : LoopNielsenEquivalent x y) :
    NielsenEquivalent (L.loopRead x) (L.loopRead y)

theorem loopNielsenStep_read {b : V} {n : ℕ}
    {x y : Fin n → Path b b} (h : LoopNielsenStep x y) :
    NielsenStep (L.loopRead x) (L.loopRead y)

theorem pathRead_mono_false {a b : V} {p : Path a b}
    (hp : L.IsMonochromatic p false) :
    ∃ g : G, L.pathRead p = Monoid.Coprod.inl g

theorem pathRead_mono_true {a b : V} {p : Path a b}
    (hp : L.IsMonochromatic p true) :
    ∃ h : H, L.pathRead p = Monoid.Coprod.inr h

theorem symmLabel_reverse {a b : Symmetrify V}
    (e : @Quiver.Hom (Symmetrify V) (@Quiver.symmetrifyQuiver V _) a b) :
    L.symmLabel (Quiver.reverse e) = factorWordInv (L.symmLabel e)

@[simp] theorem symmPathLabels_toPath {a b : Symmetrify V}
  (e : @Quiver.Hom (Symmetrify V) (@Quiver.symmetrifyQuiver V _) a b) :
    L.symmPathLabels e.toPath = [L.symmLabel e]

theorem symmPathRead_mono_false {a b : Symmetrify V}
    {p : @Quiver.Path (Symmetrify V) (@Quiver.symmetrifyQuiver V _) a b}
    (hp : L.symmIsMonochromatic p false) :
    ∃ g : G, L.symmPathRead p = Monoid.Coprod.inl g

theorem symmPathRead_mono_true {a b : Symmetrify V}
    {p : @Quiver.Path (Symmetrify V) (@Quiver.symmetrifyQuiver V _) a b}
    (hp : L.symmIsMonochromatic p true) :
    ∃ h : H, L.symmPathRead p = Monoid.Coprod.inr h

theorem symmPathRead_reverse {a b : Symmetrify V}
    (p : @Quiver.Path (Symmetrify V) (@Quiver.symmetrifyQuiver V _) a b) :
    L.symmPathRead p.reverse = (L.symmPathRead p)⁻¹

@[simp] theorem symmPathRead_toPath {a b : Symmetrify V}
    (e : @Quiver.Hom (Symmetrify V) (@Quiver.symmetrifyQuiver V _) a b) :
    L.symmPathRead e.toPath = separatedMap (L.symmLabel e)

theorem read_nielsenEquivalent {x y : Fin n → Path M.base M.base}
    (h : BinaryLabelling.LoopNielsenEquivalent x y) :
    NielsenEquivalent (M.labeling.loopRead x) (M.labeling.loopRead y)

