    (e : @Quiver.Hom (Symmetrify V) (@Quiver.symmetrifyQuiver V qV) a b) :
    symmPathEdges (qV := qV) e.toPath = [symmAllArrow e]

theorem roseEdgeSource_flip {n : ℕ} {w : Fin n → List (Sum G H)}
    (e : RoseEdge w) :
    roseEdgeSource (RoseEdge.flip e) = roseEdgeTarget e

theorem roseEdgeTarget_flip {n : ℕ} {w : Fin n → List (Sum G H)}
    (e : RoseEdge w) :
    roseEdgeTarget (RoseEdge.flip e) = roseEdgeSource e

theorem roseAllArrow_card_eq_roseEdge_card {n : ℕ}
    (w : Fin n → List (Sum G H)) :
    Fintype.card (AllArrow (V := RoseVertex w)) = Fintype.card (RoseEdge w)
